from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];T=json.loads((ROOT/'content/timeline.json').read_text());r=json.loads((ROOT/'review/reference/report.json').read_text());q=json.loads((ROOT/'review/final/report.json').read_text())
