(ROOT/'review/compare.html').write_text('''<!doctype html><meta charset="utf-8"><title>Every-frame comparison</title><style>body{font:16px system-ui;background:#252329;color:#e8e0d0;margin:30px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}video{width:100%}input{width:100%}a{color:#dac299}img{width:480px;max-width:100%;margin:5px}h2{margin-top:35px}</style><h1>Crayon-book / Leo the Farmer</h1><p>Independent frame controls. Different stories: this is a material and animation review, not a pixel-identity claim. Each atlas contains 36 consecutive frames; no sampling gaps.</p><div class="pair"><section><h2>Reference · 1,248 frames</h2><video id="r" controls src="../reference/crayon-book.mp4"></video><input type="range" min="0" max="1247" step="1" value="0" oninput="frame('r',this.value)"><output id="ro">0</output></section><section><h2>Output · '''+str(T['total_frames'])+''' frames</h2><video id="q" controls src="../media/leo-the-farmer-crayon-book.mp4"></video><input type="range" min="0" max="'''+str(T['total_frames']-1)+'''" step="1" value="0" oninput="frame('q',this.value)"><output id="qo">0</output></section></div><p><a href="final/every-output-frame-comparison.csv">Every output-frame comparison</a> · <a href="final/every-reference-frame-comparison.csv">Every reference-frame comparison</a></p><h2>Output atlas</h2>'''+''.join(f'<a href="final/{p.name}"><img loading="lazy" src="final/{p.name}" alt="{p.stem}"></a>'for p in sorted((ROOT/'review/final').glob('atlas-*.jpg')))+'''<h2>Reference atlas</h2>'''+''.join(f'<a href="reference/{p.name}"><img loading="lazy" src="reference/{p.name}" alt="{p.stem}"></a>'for p in sorted((ROOT/'review/reference').glob('atlas-*.jpg')))+'''<script>function frame(id,f){let v=document.getElementById(id);v.pause();v.currentTime=Number(f)/24+.0001;document.getElementById(id+'o').textContent='Frame '+f+' / '+(f/24).toFixed(3)+' seconds'}</script>''')
for page in [ROOT/'index.html', ROOT/'review/compare.html']:
 page.write_text(page.read_text().replace('media/leo-the-farmer-crayon-book.mp4', 'media/leo-the-farmer-crayon-book.mp4?v='+q['sha256'][:12]))
